<script setup lang="ts">
import { computed, ref, provide, reactive, useSlots } from 'vue'; import { menuKey, type MenuItem, type MenuMode } from './menu-types'; import MenuNode from './internal/MenuNode.vue';
import './styles/theme.css'; import './styles/menu.css'; import './styles/floating.css';
const props = withDefaults(defineProps<{ items: MenuItem[]; mode?: MenuMode; selectedKey?: string; defaultSelectedKey?: string; openKeys?: string[]; defaultOpenKeys?: string[]; collapsed?: boolean; theme?: 'light' | 'dark'; inlineIndent?: number; selectable?: boolean; label?: string }>(), { mode: 'inline', theme: 'light', inlineIndent: 20, selectable: true, label: '导航菜单' }); const emit = defineEmits<{ 'update:selectedKey': [key: string]; select: [key: string, item: MenuItem]; 'update:openKeys': [keys: string[]]; openChange: [keys: string[]] }>();
const inner = ref(props.defaultSelectedKey), innerOpen = ref(props.defaultOpenKeys ?? []), root = ref<HTMLElement | null>(null); const selected = computed(() => props.selectedKey ?? inner.value), opened = computed(() => props.openKeys ?? innerOpen.value); const slots = useSlots();
function keydown(event: KeyboardEvent) { const list = (event.target as HTMLElement).closest('[role=menu]'); if (!list) return; const items = Array.from(list.querySelectorAll<HTMLElement>('[role=menuitem]:not([aria-disabled=true])')).filter(element => element.getClientRects().length); if (!items.length) return; const at = items.indexOf(event.target as HTMLElement); let next: number | undefined; if (event.key === (props.mode === 'horizontal' && list === root.value ? 'ArrowRight' : 'ArrowDown')) next = (at + 1) % items.length; if (event.key === (props.mode === 'horizontal' && list === root.value ? 'ArrowLeft' : 'ArrowUp')) next = (at - 1 + items.length) % items.length; if (event.key === 'Home') next = 0; if (event.key === 'End') next = items.length - 1; if (next !== undefined) { event.preventDefault(); items[next]?.focus(); } }
provide(menuKey, reactive({ get mode() { return props.mode; }, get collapsed() { return props.collapsed; }, get selectedKey() { return selected.value; }, get openKeys() { return opened.value; }, get inlineIndent() { return props.inlineIndent; }, select(item: MenuItem) { if (item.disabled) return; item.onClick?.(item); if (!props.selectable) return; if (props.selectedKey === undefined) inner.value = item.key; emit('update:selectedKey', item.key); emit('select', item.key, item); }, toggle(key: string) { const next = opened.value.includes(key) ? opened.value.filter(item => item !== key) : [...opened.value, key]; if (props.openKeys === undefined) innerOpen.value = next; emit('update:openKeys', next); emit('openChange', next); }, render: (item: MenuItem) => slots.item?.({ item }) ?? item.label, keydown }));
function focus(event: FocusEvent) { if (event.target === root.value) root.value?.querySelector<HTMLElement>('[role=menuitem]:not([aria-disabled=true])')?.focus(); }
</script>
<template><ul ref="root" role="menu" tabindex="0" :aria-label="label" :class="['at-menu', `at-menu--${mode}`, `at-menu--${theme}`, { 'at-menu--collapsed': collapsed }]" :style="{ '--at-menu-indent': `${inlineIndent}px` }" @keydown="keydown" @focus="focus"><MenuNode v-for="item in items" :key="item.key" :item="item" /></ul></template>
